return ['project-id-version'=>'DeveloPress Sticky Footer Bar Pro','report-msgid-bugs-to'=>'','pot-creation-date'=>'2024-03-24 17:00+0000','po-revision-date'=>'2024-04-15 18:23+0000','last-translator'=>'Roberto Paolucci','language-team'=>'Spanish (Spain)','language'=>'es_ES','plural-forms'=>'nplurals=2; plural=n != 1;','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','x-generator'=>'Loco https://localise.biz/','x-loco-version'=>'2.6.7; wp-6.4.3','x-domain'=>'developress_sticky_footer_bar','messages'=>['Active'=>'Activo','Active the sticky bar'=>'Activar la barra adhesiva','Background color'=>'Color de fondo','Choose on which type of device to show the footer bar.'=>'Elige en qué tipo de dispositivo mostrar la barra de pie.','Close link in the side menu'=>'Enlace de cierre en el menú lateral','Color of menu items. Use the color picker to set it'=>'Color de los elementos del menú. Usa el selector de color para establecerlo','Contact Form'=>'Formulario de contacto','Create a footer bar, fixed to the scroll, which contains menu items. The goal is to provide a menu-level user experience similar to apps. The configuration is very simple and the customization extensive without programming knowledge.'=>'Crea una barra de pie fija al desplazamiento que contiene elementos de menú. El objetivo es proporcionar una experiencia de usuario a nivel de menú similar a las aplicaciones. La configuración es muy sencilla y la personalización es extensa sin necesidad de conocimientos de programación.','Custom CSS'=>'CSS personalizado','DeveloPress Sticky Footer Bar Pro'=>'DeveloPress Barra de Pie Fija Pro','developress.it/roberto_paolucci'=>'developress.it/roberto_paolucci','Display on all devices?'=>'¿Mostrar en todos los dispositivos?','Documentation'=>'Documentación','Everywhere'=>'En todas partes','Fantastic! This menu will be shown in the "Sticky Footer Bar" of this web site.'=>'¡Fantástico! Este menú se mostrará en la "Barra de Pie Fija" de este sitio web.','Font color of menu items'=>'Color de la fuente de los elementos del menú','Font size for menu items. Use this field to set it. Add only "number" without "px".'=>'Tamaño de la fuente para los elementos del menú. Usa este campo para establecerlo. Añade solo "número" sin "px".','Font size for other strings. Use this field to set it. Add only "number" without "px".'=>'Tamaño de la fuente para otras cadenas. Usa este campo para establecerlo. Añade solo "número" sin "px".','Font size of menu items'=>'Tamaño de la fuente de los elementos del menú','Font size othe label'=>'Tamaño de la fuente de la etiqueta','Footer bar background color. Use the color picker to set it'=>'Color de fondo de la barra del pie. Usa el selector de color para establecerlo','Hamburger menu title'=>'Título del menú hamburguesa','https://developress.it/developress-plugin/developress-sticky-footer-bar-pro/documentation/'=>'https://developress.it/developress-plugin/developress-sticky-footer-bar-pro/documentacion/','Icon size'=>'Tamaño del icono','If you have any question or need support, do not hesitate to contact me. Provide as much information as possible and try to be precise. Only in this way can I give you the best support'=>'Si tienes alguna pregunta o necesitas soporte, no dudes en contactarme. Proporciona tanta información como sea posible y sé preciso. Solo así puedo brindarte el mejor soporte.','If you have basic knowledge of HTML and CSS, you can add styling rules inside the box below. For example, you can add a different color and size to the icons.'=>'Si tienes conocimientos básicos de HTML y CSS, puedes agregar reglas de estilo en el cuadro abajo. Por ejemplo, puedes añadir un color y tamaño diferentes a los iconos.','In this section you can configure the text color, bar background and other settings.'=>'En esta sección puedes configurar el color del texto, el fondo de la barra y otros ajustes.','Need support?'=>'¿Necesitas soporte?','Number of items horizontal bar'=>'Número de ítems en la barra horizontal','Only desktop'=>'Solo escritorio','Only phone'=>'Solo teléfono','Only phone and tablet'=>'Solo teléfono y tableta','Only tablet'=>'Solo tableta','Roberto Paolucci - DeveloPress.it'=>'Roberto Paolucci - DeveloPress.it','Select icon'=>'Seleccionar icono','Settings'=>'Ajustes','Should this menu be assigned to the "Sticky Footer Bar"? If so, assign the "Stikybar" position to this menu and then save the menu.'=>'¿Debería asignarse este menú a la "Barra de Pie Fija"? Si es así, asigna la posición "Stikybar" a este menú y luego guarda el menú.','Size of icons in px. Use the field to set it. Add only "number" without "px".'=>'Tamaño de iconos en px. Usa el campo para configurarlo. Añade solo "número" sin "px".','Specifies the number of entries in the horizontal bar. The rest will be added in the side menu.'=>'Especifica el número de entradas en la barra horizontal. El resto será añadido en el menú lateral.','StickyBar Settings'=>'Configuración de StickyBar','Style and settings'=>'Estilo y configuraciones','Thanks for using the plugin! The plugin allows you to create a fixed scroll bar and customize it as you want by adding menu items and working on the style'=>'¡Gracias por usar el plugin! El plugin te permite crear una barra de desplazamiento fija y personalizarla como desees, añadiendo elementos de menú y trabajando en el estilo','Translation for the closing link of the side menu. By default, it is "Close".'=>'Traducción para el enlace de cierre del menú lateral. Por defecto, es "Cerrar".','Translation of the text of the link to the hamburger menu. By default, it is "Menu".'=>'Traducción del texto del enlace al menú hamburguesa. Por defecto, es "Menú".','When you have completed all the configurations, add the check mark in the box below to activate the footer bar.'=>'Cuando hayas completado todas las configuraciones, añade la marca de verificación en la caja abajo para activar la barra de pie de página.','You can select the menu item icon, directly on the menu management page (at the bottom of each item)'=>'Puede seleccionar el ícono del elemento del menú, directamente en la página de administración del menú (en la parte inferior de cada elemento)']];
